def compute(vars):
    shares = vars["v1"]
    exercise_price = vars["v2"]
    value = shares * exercise_price

    return {
        "value": round(value),
        "trace": {
            "shares": shares,
            "exercise_price": exercise_price,
            "calculated_value": value,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "USD"
            }
        }
    }
